async function signout(global=false){loginSync.reset();bankSyncMessage='';deviceChoice=null;devicePending=false;demo=false;session=null;household=null;recovery=false;passwordSetup.clear();accountFilter='';loadVersion++;ai=[];data=Object.fromEntries(dbTables.map(t=>[t,[]]));close();if(client){await client.removeAllChannels();check(await client.auth.signOut({scope:global?'global':'local'}))}if(vaultEnabled())AndroidVault.disable();renderAuth()}
function preview(){household=null;demo=true;session=null;month='2026-09';data=Object.fromEntries(dbTables.map(t=>[t,[]]));data.categories=defaults.map((n,i)=>({id:'c'+i,name:n,system_key:n==='Fuel'?'fuel':n==='Gas Station'?'gas_station':n==='Needs review'?'review':null,archived:false}));data.accounts=[{id:'sample',name:'Example checking',mask:'1234'},{id:'sample-savings',name:'Example savings',mask:'5678'}];const sample=[['Groceries',-17234,'Grocery market','expense',true],['Fuel',-6250,'Fuel station','expense',true],['Coffee',-1820,'Coffee shop','expense',true],['Restaurants & Dining',-7340,'Local restaurant','expense',true],['Needs review',-20000,'Payment to person','unresolved',false],['Needs review',320000,'Example payroll','income',true],['Shopping',-24300,'Online shop','expense',true]];data.transactions=sample.map(([n,a,d,k,r],i)=>({id:'t'+i,date:'2026-09-'+String(i+10).padStart(2,'0'),amount_cents:a,description:d,kind:k,reviewed:r,category_id:data.categories.find(c=>c.name===n).id,account_id:i===5?'sample-savings':'sample',note:'',source:'csv',external_id:'demo'+i}));data.financial_profiles=[{id:'demo-profile',settings:{...freshProfile(data.categories),completed:true,goals:['debt','buffer'],household:{adult:2,six:1,nine:1},monthlyIncome:600000,essentialMonthly:360000,liquidSavings:420000,extraDebt:15000,debts:[{id:'d1',name:'Example card',balance:280000,apr:22,minimum:8500,asOf:'2026-09-01',term:null},{id:'d2',name:'Example car loan',balance:950000,apr:6,minimum:29000,asOf:'2026-09-01',term:36}],vehicles:[{id:'v1',name:'Example family car',annualMiles:10787,mpg:25,priceCents:350}]}}];data.budgets=data.categories.map(c=>({id:'b'+c.id,month,category_id:c.id,amount_cents:['Groceries','Shopping'].includes(c.name)?20000:10000}));render()}
async function action(name,b){if(await planningAction(name,b))return;switch(name){case 'ai-categories':await aiCategoryDialog();break;case 'ai-categories-enable':{const choice=$('#aiCategorySelection').value,m=month,a=accountFilter;await setAiCategories(true);await runSelectedAiCategories(choice,m,a);break;}case 'ai-categories-disable':await setAiCategories(false);close();toast('Automatic AI categorization disabled.');break;case 'ai-categories-stop':aiCategoryStop=true;b.textContent='Stopping after current batch…';break;case 'ai-categories-run':await runSelectedAiCategories($('#aiCategorySelection').value,month,accountFilter);break;case 'accept-email-link':{session=await verifyEmailLink(client,authCallback);emailLinkPending=false;recovery=true;passwordSetup.begin(session.user.id);await authGate();break}case 'device-yes':{if(!session)throw Error('Enter your email and password first.');if(deviceFactorId(session.user.id)){await verifyDevice(client,session.user.id);deviceChoice='registered';await authGate()}else{const f=check(await client.auth.mfa.listFactors());if(f.all.some(x=>x.status==='verified')){devicePending=true;deviceChoice='enroll';await showMfa()}else{await enrollDevice(client,session.user.id);deviceChoice='registered';await authGate()}}break}case 'device-no':devicePending=false;deviceChoice='manual';await showMfa();break;case 'device-retry':deviceChoice=null;devicePending=false;if($('#mfaForm'))$('#mfaForm').dataset.factorId='';await showMfa();break;case 'device-enroll':if(demo||!session)throw Error('Sign in first.');await enrollDevice(client,session.user.id);render();toast('Biometric sign-in enabled. Add a backup authenticator in Manage authenticators.');break;case 'device-remove':{if(!session||demo)throw Error('Sign in first.');const fid=deviceFactorId(session.user.id),fs=check(await client.auth.mfa.listFactors()).all.filter(x=>x.status==='verified');if(!fs.some(x=>x.id!==fid&&!x.friendly_name?.startsWith('PocketNorth phone · ')))throw Error('Add and verify a backup authenticator before removing phone sign-in.');if(!confirm('Remove biometric sign-in from this phone? You will use your authenticator on your next login.'))return;if(fs.some(x=>x.id===fid))check(await client.auth.mfa.unenroll({factorId:fid}));window.AndroidDeviceFactor.remove(session.user.id);toast('Phone registration removed.');await authGate();break}case 'vault-lock':if(demo||!session||!vaultEnabled())throw Error('Sign in and enable biometric unlock first.');AndroidVault.lock();break;case 'vault-enable':if(demo)throw Error('Sign in before enabling biometric unlock.');if(!AndroidVault.isAvailable())throw Error('Set up a fingerprint or screen lock. Android 11 or newer is required.');AndroidVault.enable();break;case 'vault-disable':await signout();AndroidVault.disable();break;case 'demo':preview();break;case 'leave-demo':await signout();break;case 'close':close();break;case 'categories':categoryDialog();break;case 'import':await importStart();break;case 'choose-file':$('#importFile').value='';$('#importFile').click();break;case 'new-account':open('<h2>Add CSV account</h2><form id="accountForm"><label>Account name</label><input name="name" maxlength="100" placeholder="Household checking" required><div class="row actions"><button type="button" data-action="close">Cancel</button><button class="primary">Add account</button></div></form>');break;case 'commit-import':if(!pendingImport)return;const p=pendingImport;let result;if(demo){data.transactions.push(...p.added.map(t=>({...t,id:id()})));result={added:p.added.length,skipped:0}}else result=check(await client.rpc('import_csv',{p_account:p.account,p_rows:p.added}));pendingImport=null;month=p.added.map(t=>t.date.slice(0,7)).sort().at(-1)||month;close();tab='home';await load();toast(`${result.added} added; ${p.skipped+result.skipped} duplicates skipped.`);if(!demo&&profile().aiCategorization?.enabled){try{await runAiCategories()}catch(e){toast('Import saved. '+e.message)}}break;case 'signout':await signout();break;case 'signout-all':if(confirm('Sign out this account on all devices?'))await signout(true);break;case 'export':exportData();break;case 'password':passwordDialog();break;case 'reauth':if(demo)throw Error('Unavailable in preview.');check(await client.auth.reauthenticate());toast('Check your email for the verification code.');break;case 'email':open('<h2>Change email</h2><form id="emailForm"><label>New email</label><input name="email" type="email" autocomplete="email" required><div class="row actions"><button type="button" data-action="close">Cancel</button><button class="primary">Request change</button></div></form>');break;case 'mfa-manage':if(demo)throw Error('Authenticators require a real account.');const fs=check(await client.auth.mfa.listFactors()).all.filter(f=>f.status==='verified');open(`<h2>Your authenticators</h2><p>Keep at least one verified authenticator. Add a replacement before removing an old one.</p>${fs.map(f=>`<div class="status-line"><span>${esc(f.friendly_name||'Authenticator')} (${esc(f.factor_type)})</span><button data-remove-factor="${f.id}" ${fs.length<2||(f.factor_type==='totp'&&!f.friendly_name?.startsWith('PocketNorth phone · ')&&fs.filter(x=>x.factor_type==='totp'&&!x.friendly_name?.startsWith('PocketNorth phone · ')).length<2)?'disabled':''}>Remove</button></div>`).join('')}<button data-action="mfa-add">Add authenticator</button><button data-action="close">Done</button>`);break;case 'mfa-add':open('<h2>Add authenticator</h2><div id="mfaSetup"></div><form id="factorForm"><label>Six-digit code</label><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required><button class="primary">Verify authenticator</button></form>');await enrollInto('#mfaSetup');break;case 'connect':{const message=$('#bank-message');if(message)message.hidden=true;let j;try{j=await api('link-create')}catch(e){if(message){message.textContent=e.message;message.hidden=false;return}throw e;}open(`<h2>Continue securely with Plaid</h2><p>Authorize your accounts in the bank connection window. Then return to PocketNorth and tap Finish connection.</p><a href="${esc(j.url)}" target="_blank" rel="noopener noreferrer" id="plaid-open">Open Plaid connection ↗</a><div class="row actions"><button data-action="close">Done</button></div>`);break}case 'finish-link':{const j=await api('link-finish');toast(j.message);await load();break}case 'sync':{const j=await api('sync');await load();toast(j.message);break}case 'ai':if(!selectedAccountIds().length)throw Error('Include at least one account in Accounts, or choose an individual account.');open('<h2>Generate an AI review?</h2><p>This sends the selected accounts’ monthly category names, totals, targets, spending estimates, and review count to OpenAI. Merchant names and bank credentials are excluded.</p><p>Recommendations are suggestions based on the imported data, not a complete picture of your finances.</p><div class="row actions"><button data-action="close">Cancel</button><button data-action="ai-confirm" class="primary">Generate review</button></div>');break;case 'ai-confirm':{const requestedMonth=month,key=insightKey(),j=await api('ai',{month:requestedMonth,account_id:accountFilter||null});if(insightKey()!==key)throw Error('Spending, budgets, or account selection changed. Generate a fresh review.');ai=j.recommendations;close();tab='home';render();break}case 'delete-account':if(!confirm('Permanently delete your account and budget data, and disconnect every bank? Export a copy first.'))return;if(prompt('Type DELETE to confirm')!=='DELETE')return;await api('delete-account');await signout();toast('Account deleted.');break}}
document.addEventListener('click',async e=>{const a=e.target.closest('a#plaid-open');if(a&&window.AndroidFiles?.openExternal){e.preventDefault();AndroidFiles.openExternal(a.href);return}const b=e.target.closest('button');if(!b||b.disabled)return;b.disabled=true;try{if(b.dataset.savedReview){const review=data.ai_reviews.find(r=>r.id===b.dataset.savedReview);if(!review)return;open(`<h2>Saved household review</h2><p>${esc(review.month)} · ${esc(new Date(review.created_at).toLocaleString())}. Historical analysis; spending may have changed.</p>${(review.payload.recommendations||[]).map(r=>`<section class="notice"><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><p>${esc(r.detail)}</p></section>`).join('')}<button data-action="close">Done</button>`);return;}if(b.dataset.householdOp){const operation=b.dataset.householdOp,target=b.dataset.householdId;
const prompts={accept:'Join this household? Both partners can see and edit all of its transactions, accounts, budgets and goals. Household AI settings may send transaction details to OpenAI. Your current budget stays separate and can be selected later.',remove:'Remove this partner now? Their household access will end and bank connections they authorized will be disconnected. Existing imported transactions remain shared household records.',leave:'Leave this household? Your authorized bank connections will be disconnected. Existing imported transactions remain with the household.',revoke:'Revoke this invitation?',switch:'Switch to this household?'};
if(!confirm(prompts[operation]))return;
await api('household-manage',{operation,target});loginSync.reset();accountFilter='';close();await load();toast('Household updated.');return;}
if(b.dataset.budgetSuggestion){const suggestion=budgetSuggestions(snapshot()).find(c=>c.id===b.dataset.budgetSuggestion);if(!suggestion)throw Error('Spending changed. Refresh the recommendation.');budgetChangeDialog(suggestion.id,suggestion.proposed_target_cents);return}if(b.dataset.aiBudget!==undefined){const suggestion=ai[+b.dataset.aiBudget];budgetChangeDialog(suggestion.category_id,suggestion.proposed_target_cents);return}if(b.dataset.plan){open(toolView(b.dataset.plan,profile(),scopeRows(),month));return}if(b.dataset.debtEdit){open(debtForm(profile().debts.find(d=>d.id===b.dataset.debtEdit)));return}if(b.dataset.vehicleEdit){open(vehicleForm(profile().vehicles.find(d=>d.id===b.dataset.vehicleEdit)));return}if(b.dataset.debtDelete||b.dataset.vehicleDelete){const key=b.dataset.debtDelete?'debts':'vehicles',rid=b.dataset.debtDelete||b.dataset.vehicleDelete;if(confirm('Remove this item from your plan?')){const p=structuredClone(profile());p[key]=p[key].filter(x=>x.id!==rid);await saveProfile(p);open(toolView(key==='debts'?'debt':'fuel',profile(),scopeRows(),month))}return}if(b.dataset.password){const field=document.getElementById(b.dataset.password),show=field.type==='password';field.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password');b.setAttribute('aria-pressed',String(show));return}if(b.dataset.viewAccount){accountFilter=b.dataset.viewAccount;ai=[];tab='transactions';render()}if(b.dataset.tab){tab=b.dataset.tab;render()}if(b.dataset.auth){emailLinkPending=false;authMode=b.dataset.auth;renderAuth()}if(b.dataset.action==='captcha-retry'){mountAuthCaptcha();return}if(b.dataset.action){const authAction=['device-yes','device-enroll','device-remove'].includes(b.dataset.action);if(authAction)busy=true;try{await action(b.dataset.action,b)}finally{if(authAction)busy=false}}if(b.dataset.edit)editTransaction(data.transactions.find(t=>t.id===b.dataset.edit));if(b.dataset.insight!==undefined||b.dataset.ai!==undefined){const t=b.dataset.ai!==undefined?ai[+b.dataset.ai]:getInsights()[+b.dataset.insight];open(`<span class="eyebrow">${b.dataset.ai!==undefined?'AI recommendation':'Spending insight'}</span><h2>${esc(t.title)}</h2><p>${esc(t.body)}</p><div class="notice">${esc(t.detail||t.body)}</div><div class="row actions"><button data-action="close">Close</button>${Number.isSafeInteger(t.proposed_target_cents)?`<button data-ai-budget="${b.dataset.ai}" class="primary">Review suggested target</button>`:''}<button data-view-filter="${esc(t.filter||'')}" data-view-category="${esc(t.category_id||'')}" class="primary">View supporting transactions</button></div>`)}if(b.dataset.viewFilter!==undefined){filter=b.dataset.viewFilter;categoryFilter=b.dataset.viewCategory;query='';tab='transactions';close();render()}if(b.dataset.catEdit){const c=data.categories.find(c=>c.id===b.dataset.catEdit);open(`<h2>Edit category</h2><form id="categoryEdit" data-id="${c.id}"><label>Name</label><input name="name" maxlength="80" value="${esc(c.name)}" required><div class="row actions"><button type="button" data-action="close">Cancel</button><button class="primary">Save name</button></div></form>`)}if(b.dataset.catDelete){const c=data.categories.find(c=>c.id===b.dataset.catDelete);open(`<h2>Delete ${esc(c.name)}?</h2><p>Existing transactions and targets will move to the replacement. Monthly target amounts will be combined.</p><form id="categoryDelete" data-id="${c.id}"><label>Replacement category</label><select name="replacement">${options(data.categories.filter(x=>x.id!==c.id&&!x.archived))}</select><div class="row actions"><button type="button" data-action="close">Cancel</button><button class="danger">Delete & reassign</button></div></form>`)}if(b.dataset.disconnect&&confirm('Disconnect this bank? Existing imported transactions remain.')){await api('disconnect',{item_id:b.dataset.disconnect});await load()}if(b.dataset.reconnect){const j=await api('link-create',{item_id:b.dataset.reconnect});open(`<h2>Reconnect bank</h2><a href="${esc(j.url)}" target="_blank" rel="noopener noreferrer" id="plaid-open">Open Plaid ↗</a><p>Return and choose Finish connection.</p><button data-action="close">Done</button>`)}if(b.dataset.removeFactor&&confirm('Remove this authenticator?')){const factors=check(await client.auth.mfa.listFactors()).all.filter(x=>x.status==='verified');const removing=factors.find(x=>x.id===b.dataset.removeFactor);if(removing&&!removing.friendly_name?.startsWith('PocketNorth phone · ')&&factors.filter(x=>!x.friendly_name?.startsWith('PocketNorth phone · ')).length<2)throw Error('Add another backup authenticator before removing this one.');check(await client.auth.mfa.unenroll({factorId:b.dataset.removeFactor}));if(session&&deviceFactorId(session.user.id)===b.dataset.removeFactor)window.AndroidDeviceFactor.remove(session.user.id);close();toast('Authenticator removed.')}}catch(e){fail(e)}finally{if(b.isConnected)b.disabled=false}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const f=e.target,fd=new FormData(f),submit=f.querySelector('button[type=submit],button.primary');if(submit)submit.disabled=true;try{if(await planningSubmit(f,fd))return;switch(f.id){case 'partnerAccess':{check(await client.rpc('set_partner_accounts',{p_accounts:fd.getAll('partnerAccount')}));await load();toast('Partner account access saved.');break}case 'householdInvite':{const r=await api('household-invite',{email:fd.get('email')});await load();toast(r.message);break}case 'accountPreferences':await saveAccountPreferences(fd.getAll('includedAccount'));break;case 'authForm':{if(config.inviteOnly&&authMode==='signup')throw Error('PocketNorth is invite-only.');const email=$('#authEmail').value,password=$('#authPassword')?.value;check(await submitAuth({client,mode:authMode,email,password,redirectTo:baseURL(),captcha}));if(authMode==='signup'){renderAuth('Check your email to confirm your account.')}else if(authMode==='reset'){renderAuth('If that account exists, a password-reset email has been sent.')}else {recovery=false;passwordSetup.clear();history.replaceState(null,'',baseURL());captcha.clear();await authGate()}break}case 'mfaForm':await verifyMfa(f,$('#mfaCode').value);await authGate();break;case 'factorForm':await verifyMfa(f,fd.get('code'));close();await authGate();break;case 'categoryAdd':await insert('categories',{name:fd.get('name').trim()});await load();categoryDialog();break;case 'categoryEdit':await update('categories',f.dataset.id,{name:fd.get('name').trim()});close();await load();break;case 'categoryDelete':if(demo){const old=f.dataset.id,replacement=fd.get('replacement');for(const table of ['transactions','budgets','merchant_rules'])for(const r of data[table])if(r.category_id===old)r.category_id=replacement;const combined=new Map();for(const r of data.budgets){const key=r.month+':'+r.category_id;const prior=combined.get(key);if(prior)prior.amount_cents+=r.amount_cents;else combined.set(key,r)}data.budgets=[...combined.values()];data.categories=data.categories.filter(c=>c.id!==old)}else check(await client.rpc('delete_category',{p_id:f.dataset.id,p_replacement:fd.get('replacement')}));close();await load();break;case 'accountForm':await insert('accounts',{name:fd.get('name').trim()});close();await load();break;case 'transactionForm':{const t=data.transactions.find(t=>t.id===f.dataset.id),patch={category_id:fd.get('category'),kind:fd.get('kind'),note:fd.get('note'),excluded:fd.has('excluded'),reviewed:fd.get('kind')!=='unresolved',manual_category:true};const matches=fd.has('remember')?merchantReviewUpdates(data.transactions,t,patch,data.categories):[];await update('transactions',t.id,patch,t.updated_at);let result={saved:0,failed:0};if(fd.has('remember')){const r=data.merchant_rules.find(r=>norm(r.merchant)===norm(t.description));if(r)await update('merchant_rules',r.id,{category_id:patch.category_id,kind:patch.kind});else await insert('merchant_rules',{merchant:norm(t.description),category_id:patch.category_id,kind:patch.kind});result=await applyMerchantReviews(matches,update)}close();await load();toast(result.failed?`Saved this transaction and ${result.saved} matching transactions. ${result.failed} could not be updated; review the remaining items and retry.`:result.saved?`Saved and marked ${result.saved+1} transactions reviewed. Merchant remembered for future imports.`:'Transaction saved.');break}case 'setupPasswordForm':{if(!session||!recovery)throw Error('Open a valid password-reset email first.');if(fd.get('password')!==fd.get('confirm'))throw Error('The passwords do not match.');check(await client.auth.updateUser({password:fd.get('password')}));recovery=false;passwordSetup.clear();history.replaceState(null,'',baseURL());await authGate();toast('Password saved.');break}case 'passwordForm':if(demo)throw Error('Sign in to change your password.');check(await client.auth.updateUser({password:fd.get('password'),...(fd.get('nonce')?{nonce:fd.get('nonce')}:{})}));recovery=false;passwordSetup.clear();history.replaceState(null,'',baseURL());close();toast('Password updated.');break;case 'emailForm':if(demo)throw Error('Sign in to change your email.');check(await client.auth.updateUser({email:fd.get('email')},{emailRedirectTo:baseURL()}));close();toast('Check your current and new email for confirmation.');break}}catch(e){fail(e)}finally{busy=false;if(submit)submit.disabled=false}});
document.addEventListener('change',async e=>{try{if(e.target.id==='darkMode'){e.target.disabled=true;try{await saveTheme(e.target.checked)}finally{if(e.target.isConnected)e.target.disabled=false}return;}if(e.target.id==='accountScope'){accountFilter=e.target.value;ai=[];render()}if(e.target.id==='month'){month=e.target.value;ai=[];render()}if(e.target.id==='filter'){filter=e.target.value;renderTransactions()}if(e.target.id==='categoryFilter'){categoryFilter=e.target.value;renderTransactions()}if(e.target.dataset.budget){const category_id=e.target.dataset.budget,n=Number(e.target.value);if(e.target.value===''||n<0||!Number.isFinite(n))throw Error('Enter a nonnegative target.');const b=monthBudget().find(b=>b.category_id===category_id);if(b)await update('budgets',b.id,{amount_cents:Math.round(n*100)},b.updated_at);else await insert('budgets',{month,category_id,amount_cents:Math.round(n*100)});await load();toast('Target saved.')}if(e.target.id==='importFile')await handleImport(e.target.files[0])}catch(e){fail(e)}});
document.addEventListener('input',e=>{if(e.target.id==='query'){const pos=e.target.selectionStart;query=e.target.value;renderTransactions();$('#query').focus();$('#query').setSelectionRange(pos,pos)}});
for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>lastActive=Date.now(),{passive:true});setInterval(()=>{if(session&&!demo&&!vaultLocked()&&Date.now()-lastActive>config.idleMinutes*60000){if(vaultEnabled())AndroidVault.lock();else signout().then(()=>toast('Signed out after inactivity.')).catch(fail)}},15000);
window.addEventListener('focus',()=>{if(session&&!demo&&!vaultLocked()&&!busy&&!$('#mfaForm')&&!$('#factorForm'))authGate().catch(fail)});
window.addEventListener('pocketnorth-vault-enabled',()=>{try{for(const key of Object.keys(sessionStorage)){if(key.startsWith('sb-nsnvijabnzqqcxbuwdlk-auth-token')){AndroidVault.setItem(key,sessionStorage.getItem(key));sessionStorage.removeItem(key)}}lastActive=Date.now();render();toast('Biometric unlock enabled. Your login is encrypted on this device.')}catch(e){fail(e)}});
window.addEventListener('pocketnorth-unlocked',()=>{loginSync.reset();lastActive=Date.now();if(client)authGate().catch(fail)});
if(new URLSearchParams(location.search).has('bank_return')){$('#app').innerHTML='<main class="auth-form"><div class="brand"><img src="./icon.svg" alt="">PocketNorth</div><h1>Return to your budget.</h1><p>The bank connection window has finished. Return to the original PocketNorth tab or Android app and tap <b>Finish connection</b>.</p></main>';}else if(new URLSearchParams(location.search).has('demo'))preview();else if(config.supabaseUrl&&config.supabaseKey){if(location.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(location.hostname)){$('#app').textContent='PocketNorth requires HTTPS.'}else {recovery=authCallback.passwordSetup;client=createClient(config.supabaseUrl,config.supabaseKey,{auth:{storage:authStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:authCallback.flowType}});client.auth.onAuthStateChange((event,s)=>{if(event==='PASSWORD_RECOVERY')recovery=true;if(event==='SIGNED_OUT'){household=null;recovery=false;passwordSetup.clear();loginSync.reset();bankSyncMessage='';session=null;data=Object.fromEntries(dbTables.map(t=>[t,[]]));renderAuth()}if(event==='TOKEN_REFRESHED')session=s});if(authCallback.errorMessage){history.replaceState(null,'',baseURL());renderAuth(authCallback.errorMessage)}else if(emailLinkPending){history.replaceState(null,'',baseURL());renderEmailLink()}else authGate().catch(e=>renderAuth('Unable to complete the email sign-in. '+e.message));}}else if(new URLSearchParams(location.search).has('demo'))preview();else renderAuth();

setInterval(async()=>{if(!session||demo||document.hidden||busy)return;try{const current=await api('household-context');if(household&&(current.id!==household.id||current.access_version!==household.access_version||current.restricted!==household.restricted)){close();accountFilter='';data=Object.fromEntries(dbTables.map(t=>[t,[]]));household=current;await load();toast('Household access changed. Your current household has been refreshed.')}}catch{}},30000);

function memberLabel(user){return user===session?.user.id?'you':household?.members?.find(m=>m.user_id===user)?.email||'a household member'}
function householdPanel(){if(demo)return '<section class="panel appearance-panel"><h2>Household</h2><p>Sign in to invite a partner with their own secure login.</p></section>';if(!household)return '';return `<section class="panel appearance-panel"><h2>Household</h2><p><b>${esc(household.name)}</b> · You are the ${esc(household.role)}.</p><p>The owner chooses which accounts the partner can access. Categories and budget targets remain shared. The All accounts totals setting is separate from these privacy controls.</p>${partnerAccessPanel()}${household.members.map(m=>`<div class="status-line"><span>${esc(m.email)} · ${esc(m.role)}</span>${household.role==='owner'&&m.role==='partner'?`<button data-household-op="remove" data-household-id="${m.user_id}">Remove partner</button>`:''}</div>`).join('')}${household.role==='partner'?'<button data-household-op="leave">Leave household</button>':''}${household.role==='owner'&&household.members.length<2?'<form id="householdInvite"><label for="partnerEmail">Partner email</label><input id="partnerEmail" name="email" type="email" maxlength="254" autocomplete="email" required placeholder="partner@example.com"><button type="submit" class="primary">Send partner invitation</button><p class="footnote">Invitations expire in 7 days. Sending another revokes the previous household invitation. Your partner will create a password, set up MFA or supported phone biometrics, then accept after signing in. Both people can disconnect banks they authorize; the owner can manage every connection.</p></form>':''}${household.invitations.map(i=>`<div class="notice">Invitation pending for ${esc(i.email)}. Expires ${esc(new Date(i.expires_at).toLocaleDateString())}. <button data-household-op="revoke" data-household-id="${i.id}">Revoke invitation</button></div>`).join('')}${household.pending.map(i=>`<div class="notice"><h3>Invitation to ${esc(i.name)}</h3><p>Accept to access the accounts the owner shares with you. Your existing budget stays separate. The invitation must match your verified email.</p><button class="primary" data-household-op="accept" data-household-id="${i.id}">Accept household invitation</button></div>`).join('')}${household.households.length>1?`<h3>Your households</h3>${household.households.map(h=>`<button data-household-op="switch" data-household-id="${h.id}" ${h.id===household.id?'disabled':''}>${h.id===session?.user.id?'My own household':esc(h.name)}${h.id===household.id?' (current)':''}</button>`).join('')}`:''}</section>`}

function sharedReviewCards(){const reviews=(data.ai_reviews||[]).filter(r=>r.month===month).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,3);return reviews.length?`<section class="panel section-head"><div><h2>Saved household AI reviews</h2><p class="muted">Historical snapshots shared with your partner. Generate a fresh review when spending changes.</p>${reviews.map(r=>`<button data-saved-review="${r.id}">${esc(new Date(r.created_at).toLocaleString())} · ${r.payload.account_id?'Individual account':'Included accounts'}</button>`).join('')}</div></section>`:''}

function partnerAccessPanel(){if(household?.role!=='owner')return '<p class="notice">Your account access is managed by the household owner.</p>';return `<form id="partnerAccess"><h3>Partner account access</h3><p>Check the accounts your partner may see and review. Unchecked accounts and their transactions stay private. New accounts are private by default. Choose these before sending an invitation.</p>${data.accounts.map(a=>`<label class="account-check"><input type="checkbox" name="partnerAccount" value="${esc(a.id)}" ${a.partner_visible?'checked':''}><span>${esc(accountLabel(a))}</span></label>`).join('')||'<p>No accounts yet. Connect a bank or add a CSV account first.</p>'}<button type="submit" class="primary">Save partner account access</button><p class="footnote">Categories and budget targets remain shared. When access is limited, the household financial profile, debt plan and merchant-wide rules stay owner-only to protect private details. Previously viewed or downloaded information cannot be recalled.</p></form>`}
